'use strict';

// CC-1360 F26: commander/cowork-plugin-codex is generated by `npm run
// build:codex` and committed. codex-build.test.js checks a fresh build in a
// temp dir but never compares it with the committed tree, so an edit to
// cowork-plugin/ without a rebuild shipped a stale Codex plugin. This test
// rebuilds into a temp dir and requires the committed mirror to match it.

const test = require('node:test');
const assert = require('node:assert');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const REPO = path.join(__dirname, '..', '..');
const MIRROR = path.join(REPO, 'commander', 'cowork-plugin-codex');
// Hand-authored, preserved across rebuilds by build-codex.js (CC-859).
const HAND_AUTHORED = new Set(['README.md']);

function listFiles(root, rel = '') {
  const out = [];
  for (const entry of fs.readdirSync(path.join(root, rel), { withFileTypes: true })) {
    const p = path.join(rel, entry.name);
    if (entry.isDirectory()) out.push(...listFiles(root, p));
    else out.push(p);
  }
  return out;
}

test('committed Codex mirror matches a fresh build:codex', function (t) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ccc-codex-drift-'));
  t.after(function () { fs.rmSync(tmp, { recursive: true, force: true }); });
  const out = path.join(tmp, 'out');
  const r = spawnSync(process.execPath, [path.join(REPO, 'scripts', 'build-codex.js'), '--out', out], {
    cwd: REPO, encoding: 'utf8', timeout: 120000,
  });
  assert.strictEqual(r.status, 0, 'build-codex failed: ' + r.stderr);

  const built = listFiles(out).sort();
  const committed = listFiles(MIRROR).filter((f) => !HAND_AUTHORED.has(f)).sort();
  const missing = built.filter((f) => !committed.includes(f));
  const extra = committed.filter((f) => !built.includes(f));
  const changed = built.filter((f) => committed.includes(f)
    && !fs.readFileSync(path.join(out, f)).equals(fs.readFileSync(path.join(MIRROR, f))));

  const hint = ' (run `npm run build:codex` and commit commander/cowork-plugin-codex)';
  assert.deepStrictEqual(missing, [], 'missing from the committed mirror' + hint);
  assert.deepStrictEqual(extra, [], 'stale files in the committed mirror' + hint);
  assert.deepStrictEqual(changed, [], 'out of date in the committed mirror' + hint);
});
